def next_steps(graph, start, seen):
    steps = []
    q = deque([start])
    while q:
        v = q.popleft()
        for neighbor in graph[v]:
            if neighbor not in seen:
                steps.append(neighbor)
                q.append(neighbor)
                seen.add(neighbor)
                if len(steps) == n // k:
                    break
    return steps

def solve_for_johnny(graph, m):
    n = len(graph)
    degrees = [sum(1 for v in graph if v == i) for i in range(n)]
    if max(degrees) < 3:
        return -1
    total_degrees = sum(degrees)
    k = n // total_degrees * total_degrees
    total_cycles = total_degrees // 3
    if k > total_cycles:
        return -1
    cycles = [
        next_steps(graph, start, visited)
        for start in range(n)
        if degrees[start] - 1 - (n % degrees[start]) % 3 == k
    ]
    return CYCLES, len(cycles), "\n".join([" ".join(map(str, cycle)) for cycle in cycles])

