from typing import List
from collections import defaultdict, deque

def count_good_strings(n: int, m: int, k: int) -> int:
    # Parse graph data
    graph = defaultdict(list)
    for _ in range(m):
        a, b = map(int, input().split())
        graph[a-1].append(b-1)
        graph[b-1].append(a-1)

    # Function to check if a graph has a path of length 2*i
    def has_path_for_level(x: int, i: int) -> bool:
        queue = deque([x])
        while queue:
            node = queue.popleft()
            for nei in graph[node]:
                if nei == x:
                    continue
                if i + 1 == 2 * nei or i + 2 == 2 * nei:
                    return True
                queue.append(nei)
        return False

    # Function to check if a path is palindromic
    def is_palindromic_path(path: List[int], node: int) -> bool:
        while node < len(path) - 1:
            if path[node] != path[-1 * (node - len(path) + 2) - 1]:
                return False
            node += 1
        return True

    path_count = 0
    for start in range(n):
        vertices = [start]
        while n != len(vertices) and has_path_for_level(start, len(vertices)):
            if is_palindromic_path(vertices, start):
                path_count += 1
            for u in graph[start]:
                if u not in vertices:
                    vertices.append(u)

    return path_count

