def func(s, t, c, d):
    f = 0
    for char in s:
        if d >= 0:
            if d < len(t[i]) and t[i][d] == char:
                c[i] -= 1
                f += c[i]
            d += 1
        else:
            if d < len(t[i]) and t[i][d] == char:
                c[i] -= 1
                d -= 1
            d += 1
    return f

def max_value(n, t, c):
    length = 0
    res = 0
    for i in t:
        length += len(i)
    counts = []
    ds = [-1] * n
    mx = [0] * (n - 1)
    for i in range(n - 1):
        for j in range(i + 1, n):
            k = 0
            while k < length and i < t[k] and j < t[k]:
                if len(t[k]) == t[i][-1] + k - i and t[k][k] == t[i][-1]:
                    mx[k] = func(t[i][k:], t[j][k:], c[j], k)
                    if mx[k] > 0:
                        mx[k] = (i - min(i, j)) * c[j]
                        ds[k] = j
                k += 1
            result = (0, None)
            chain = None
            for k in range(i + 1, n):
                if t[k][-1] == t[i][-1] and mx[k] > result[0]:
                    result = (mx[k], k)
                    chain = k
            if result[0] > res:
                dt = t.copy()
                dt.pop(chain)
                result = result
                while result[1] is not None:
                    dt.pop(result[1])
                    result = t.pop(chain)
                res = result
            counts.append(dt)
    res = 0
    while len(res) < len(n):
        res = [max(res, func(x, counts.pop(), c, i)) + res[i] for i, x in enumerate(t)]
    return max(res)
