def count_perfect_sets(k):
    if k == 0:
        return 1  # Base case: There is only one set containing 0 if there are no numbers in the set

    mod = 1000000007  # Given modulo value

    # Function to check if a set is perfect
    def is_perfect(num):
        return num == 0 or num == 1

    # Function to calculate perfect sets under modulo
    def perfect_sets_count(num):
        if num == 0:
            return 1
        elif num == 1 or num == 2:
            return 1
        elif num == 3:
            return 2
        elif num == 4:
            return 3
        else:
            return (perfect_sets_count(num-1) + perfect_sets_count(num-2)) % mod

    # Apply the function for input value k
    return perfect_sets_count(k)

