def perfect_sets(k):
    mod = 1000000007
    if k == 0:
        return 1  # {0} is the only perfect set for k=0
    if k == 1:
        return 2  # {0}, {0, 1}
    # For k >= 2, the number of perfect sets can be derived from the sequence a(n) where
    #  a(0) = 1, a(1) = 2, and a(n) = a(n-1) + (2^(n-2)) - 1 for n >= 2
    return a = a(n) mod mod

