from math import factorial

def factorial_mod(n, mod):
    """Function to calculate factorial modulo a prime."""
    if n < 0 or mod < 2:
        raise ValueError("n should be non-negative and mod should be greater than 1.")
    if n == 0 or n == 1:
        return 1
    return factorial(n) % mod

def f_pended_mod(k, n, mod):
    """Helper function to compute dp table f_k[j] which gives the number of sequences with a hole of size <= j."""
    dp = [0] * (n + 1)
    dp[0] = 1
    for j in range(1, n + 1):
        for i in range(1, j + 1):
            if i * (j // i) < k + 1:
                dp[j] = (dp[j] + dp[j - i]) % mod
    return dp[-1]

def f_sequence(n, mod):
    """Return a list where each element [i] corresponds to ∑_{p∈ s_n} f_p(i) mod mod."""
    prev_length = 1
    num_elements = [0] * n
    last_special = -1
    for i in range(2, n + 1):
        if i <= prev_length + 1:
            num_elements[i - 1] -= f_pended_mod(last_special, i - last_special, mod)
            if i == prev_length + 1:
                continue
            num_elements[i - 1] += num_elements[i - 2] * i
        elif i * i >= n:
            num_elements[i - 1] += num_elements[i - 2]
            if i // 2 > i ** 2 // 2:
                last_special = i - 1 
        else:
            while i * i > n:
                prev_length = i
                num_elements[i - 1] = num_elements[i - 2]
                last_special = i - 1    
            num_elements[i - 1] += num_elements[i - 2] * i
            if i * (i // 2 + i % 2) > n:
                last_special = i - 1
        num_elements[i - 1] = num_elements[i - 1] % mod
    return num_elements

