def is_defended(n, m, rooks, areas):
    rooks.sort()
    vertical_rooks = [(x, True) for x, _ in rooks]
    horizontal_rooks = [(False, y) for _, y in rooks]

    queens = set(vertical_rooks + horizontal_rooks)

    for v, h in areas:
        if v <= n // 2 <= h and (vertical_rooks[0][1] or v % 2 == 1):
            queens.discard(vertical_rooks[0])
            vertical_rooks = vertical_rooks[1:]

        if v % 2 == 1:
            agents = queens - {col for col, _ in vertical_rooks}
            alphas = (1 << 20) if v % 2 == 0 else 0
            for alpha in agents:
                row = min(h, v)
                col = min(alpha - 1, 20) if row % 2 == 0 else min(h, (alpha + 1) % 20)
                if row in agents or col in agents:
                    continue
                if row in queens:
                    alphas = 0
                if col == (20 if row % 2 == 0 else min(19, 20)) and (row * (m + 1) + min(alpha // 20, alpha // 20 + 1) + 1) in queens or (row + (min(alpha % 20, 19)) == m and (alpha + 1) % 20 in queens):
                    continue
                q = float("inf")
                for r in range(1, m // 2 + 1):
                    if (r + (alpha * r) % (m + 1)) in agents:
                        q = min(row, r + (alpha * r) % (m + 1))
                        break
                    elif (r + (alpha * r) % (m + 1)) in queens:
                        q = min(r + (alpha * r) % (m + 1), alpha // 20 if row % 2 == 0 else alpha % 20)
                        break
                queens |= {col for col, _ in horizontal_rooks if col < q}
