        for i, (_, count) in enumerate(self.counts, 1):
            if index in count:
                count[index] += 1 if i in self.counts else 0
                if i > 1:
                    self.counts[i-1].pop(index)
        self.counts[index] = {index: 1}

    def remove(self, index):
