        for i, (surname, count) in enumerate(self.counts):
            if index in count:
                count[index] -= 1
                self.counts[i].pop(index)
            if count[index] == 0:
                del self.counts[i][index]

    def calculate_politicization(self, text):
        politicization = {s: 0 for s in self.surnames}
