def max_connected_component(n, k, grid):
    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < n

    def bfs(x, y):
        queue = [(x, y)]
        path = {(x, y)}
        while queue:
            x, y = queue.pop()
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                if is_valid(x+dx, y+dy) and (x+dx, y+dy) not in path:
                    path.add((x+dx, y+dy))
                    queue.append((x+dx, y+dy))

        return len(path)

    max_size = 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == '.':
                region_size = bfs(i, j)
                max_size = max(max_size, region_size)

    return k ** 2 if k ** 2 <= max_size else max_size

