def calculate_perfect_sets(k):
    # Base case: When k is 0, there is exactly one perfect set (the empty set)
    if k == 0:
        return 1
    # Base case: When k is 1, there are two perfect sets (the set containing 0 or the set containing 0 and 1)
    elif k == 1:
        return 2
    # Recursive case: Calculate the number of perfect sets using the recursive formula
    else:
