            for row_start in range(i, i + k):
                for col_start in range(j, j + k):
                    if grid[row_start % n] == 'X':
                        break
                    grid[row_start % n] = '.'
            else:
                largest_component = 1
                queue = [(i, j)]
                while queue:
                    current = queue.pop(0)
                    for neighbor in get_neighbors(current[0], current[1]):
                        if neighbor['is_blocked'] and neighbor['is_empty']:
                            grid[neighbor['row']] = 'X'
                            new_component = 1 + neighbor['is_empty']
                            largest_component = max(largest_component, new_component)
                            queue.append(neighbor)
                max_size = max(max_size, largest_component)
    return max_size

def get_neighbors(row: int, col: int) -> List[Tuple[int, int, bool]]:
    neighbors = []
    for dr in range(-1, 2):
        for dc in range(-1, 2):
            if not (dr == 0 and dc == 0) and 0 <= (row + dr) % n and 0 <= (col + dc) % n:
                neighbors.append((row + dr, col + dc, bool(grid[row + dr][col + dc] == '#')))
    return neighbors

