def bfs(start, grid):
    n, m, queue = len(grid), len(grid[0]), deque([start])
    seen = set([start])
    connections = count(0, size=1)

    while queue:
        r, c = queue.popleft()
        cx, cy = (c-r) % 2, (c+r) % 2
        for r1, c1 in (r-1, c), (r+1, c), (r, c-1), (r, c+1):
            if 0 <= r1 < n and 0 <= c1 < m and grid[r1][c1] == '.':
                neighbor = (r1, c1), connections.next()
                if neighbor not in seen:
                    seen.add(neighbor)
                    queue.append(neighbor)

    return list(seen)

def pour(grid, k):
    n = len(grid)
    maxsize = 0
    for i in count(0, size=k):
        xs = list()
        r = []
        for j in count(0, size=k):
            y, x = (i-j) % n, j
            rng = y // k + 1
            mx = max(r, key=lambda a: bfs(a)[0:2*n+2][(y+a)%2*n]*rng)
            if mx > xs:
                xs = [
                    m-1 for m in r if n*(m > i) + n*m + (m > j) in [n*(m > ai) + n*m + (m > mj) for ai, aj in (
                    (i < ai) and (j < aj) and (isinstance(ai, float) and isinstance(aj, float) and ai > aj)
                  )] * rng + i + j * rng
                ]
            r = (mx, max(r, key=lambda a: min(x, mx - x, a)))
            maxsize = max(maxsize, sum([min(x, mx - x)] * 2*n + 2), r[1])
    return maxsize

