from collections import deque

def find_path_or_cycles(graph, degree, k, required_n):
    n = len(graph)
    if required_n % k != 0:
        # If the numerator of n/k is not k, there's no valid path for Johnny
        ans = -1
    else:
        # Use BFS to find a path for Johnny, or Eulerian path for Solving
        bfs_buffer = deque()
        answer = []
        for i in range(degree):
            bfs_buffer.append((0+i, 1))
        visited = [False] * n
        valid = True
        while bfs_buffer and valid:
            e = bfs_buffer.popleft()
            if e[1] not in graph[e[0]]:
                # Break if degree becomes negative
                return -1
            vv, ee = e
            if not visited[vv]:
                visited[vv] = True
                ne_v = [v for v in graph[vv] if visited[v] is False]
                if len(ne_v) < k:
                    # Break if degree does not contain a cycle
                    return -1
                if all([ele in answer for ele in ne_v]):
                    # Break the infinite reach loop
                    return -1
                bfs_buffer.extend((ele, vv) for ele in ne_v)
        for v, i in bfs_buffer:
            if answer and answer[-1] in graph[v] and v not in answer:
                # Found not disqualified cycle basicaly, strip it down to solve
                assert i == 0
                if v not in answer:
                    answer.append(v)
        required_n -= len(bfs_buffer)
        if valid:
            ans = max(bfs_buffer)
        answer += abs(required_n)
        while ans:
            if not answer:
                answer = []
                valid = False
                break
            v, i = ans
            if i:
                assert v not in answer
                answer.append(v)
            ne_v = [v for v in graph[v] if not answer or answer[-1] in graph[v] and v not in answer]
            assert len(ne_v) == 1, ne_v
            edge = [vv for v, vv in graph[vv] if i == 0][0]
            if ne_v[0] == edge:
                graph[edge].remove(v)
            else:
                graph[v].remove(edge)
        for i in range(len(answer)-1, -1, -1):
            print(" ".join(str(e+1) for e in answer[:i+1]))
        print(ans)
    return ans

def solve():
    n, m, k = map(int, input().split())
    graph = [[set() for _ in range(n+1)] for _ in range(n+1)]
    for _ in range(m):
        u, v = map(int, input().split())
        graph[u][v].add(v)
        graph[v][u].add(u)
    return find_path_or_cycles(graph, n, k, n // k)

