def is_rectangle_defended(n, m, k, areas):
    # Create a list of all possible horizontal and vertical rook positions
    horizontal_rook_positions = [(x, y) for y in range(1, m+1) for x in range(1, n+1)]
    vertical_rook_positions = [(x, y) for x in range(1, n+1) for y in range(1, m+1)]

    defended = set()

    for start in horizontal_rook_positions + vertical_rook_positions:
        rook_positions = [start] + list(itertools.takewhile(lambda x: x[1] == start[1], iterative_neighbors(start[0], horizontal_rook_positions, vertical_rook_positions)))

        if is_valid(rook_positions, areas):
            for rpos in rook_positions:
                defended.add((rpos[0], rpos[1]))

    return len(defended) == len(set(itertools.chain.from_iterable(areas)))

def is_valid(rook_positions, areas):
    # Check if all cells of the area are within the board
