def extended_gcd(a, b, m):
    """
    Extended Euclidean Algorithm to find x and y such that a*x + b*y = gcd(a, b)
    Returns a tuple (gcd, x, y)
    """
    if a == 0:
        return (b, 0, 1)
    gcd, x1, y1 = extended_gcd(b % a, a, m)
    x = y1 - (b // a) * x1
    y = x1
