from sortedcontainers import SortedList

def bob_process(requests):
    leftpoints = SortedList()
    rightpoints = SortedList()

    for request in requests:
        data = request.split()
        if data[0] == 'add':
            x, y = map(int, data[1:])
            point = (x, y)
            leftpoints.add(point)
            if rightpoints and x > rightpoints[-1][0]:
                for point in rightpoints:
                    if x >= point[0] and y <= point[1]:
                        rightpoints.remove(point)
                if leftpoints and rightpoints and leftpoints[0][0] < rightpoints[0][0]:
                    leftpoints = leftpoints[:1]
        elif data[0] == 'remove':
            x, y = map(int, data[1:])
            point = (x, y)
            if point not in rightpoints:
                leftpoints.discard(point)
        elif data[0] == 'find':
            x, y = map(int, data[1:])
            if leftpoints and leftpoints[0][0] < x and (leftpoints or rightpoints):
                point = next(k for k in leftpoints if k[0] >= x)
            elif rightpoints and rightpoints[0][0] >= x:
                point = rightpoints.bisect_left((x, x))
                if point:
                    point = rightpoints[point - 1]
            else:
                point = -1
            print(f"{point[0]} {point[1]}")
